import itertools

n = 17
edges = set()
for i in range(n):
    edges.add((i, (i+1) % n))
    edges.add((i, (i+2) % n))

edges = [(min(u,v), max(u,v)) for (u,v) in edges]
edges = sorted(set(edges))

# Build adjacency
adj = {i: set() for i in range(n)}
for u,v in edges:
    adj[u].add(v)
    adj[v].add(u)

def is_connected(vertices, adj):
    """Check if the subgraph induced by vertices is connected"""
    if len(vertices) <= 1:
        return True
    start = next(iter(vertices))
    visited = set([start])
    stack = [start]
    while stack:
        v = stack.pop()
        for nb in adj[v]:
            if nb in vertices and nb not in visited:
                visited.add(nb)
                stack.append(nb)
    return len(visited) == len(vertices)

def vertex_connectivity(adj, n):
    """Check if vertex-connectivity >= 4 by checking all subsets of size <= 3"""
    all_vertices = set(range(n))

    # Check subsets of size 0, 1, 2, 3
    for k in range(4):
        for subset in itertools.combinations(range(n), k):
            removed = set(subset)
            remaining = all_vertices - removed
            if len(remaining) <= 1:
                continue
            # Check if remaining is connected
            if not is_connected(remaining, adj):
                return k  # Found a cut set of size k
    return 4  # No cut set of size <= 3 found

print("Vertex connectivity:", vertex_connectivity(adj, n))
